#include <vector>

int count_up_days(const std::vector<double>& prices) {
    int ups = 0;
    for (std::size_t i = 1; i < prices.size(); ++i) {
        if (prices[i] > prices[i - 1]) {
            ++ups;
        }
    }
    return ups;
}

