widget.solution:
#include <vector>

double max_drawdown(const std::vector<double>& prices) {
    double peak = 0;
    double worst = 0;
    for (double p : prices) {
        if (p > peak) {
            peak = p;
        }
        double fall = (peak - p) / peak;
        if (fall > worst) {
            worst = fall;
        }
    }
    return worst;
}

