widget.solution:
#include <string>
#include <vector>

std::vector<int> fills_by_venue(const std::string& venues) {
    std::vector<int> counts(4, 0);  // LSE, Cboe, Turquoise, other
    for (char v : venues) {
        switch (v) {
            case 'L': ++counts[0]; break;
            case 'C': ++counts[1]; break;
            case 'T': ++counts[2]; break;
            default: ++counts[3]; break;
        }
    }
    return counts;
}

